export type WorkflowFileStep = ({
  agent: string;
  asks_first: boolean;
  if_it_fails?: IfItFails;
  kind: "agent";
  line: string;
  ordin_checks: boolean;
  /** Display number: "3", "2.1", "3a"; steps sharing a number with letters run at the same time. */
  position: string;
  uses: StepUse[];
} | {
  decided_by: Decider;
  kind: "if";
  paths: NamedPath[];
  position: string;
} | {
  kind: "for_each";
  list: ListSource;
  max_items: number;
  position: string;
  steps: WorkflowFileStep[];
} | {
  decided_by: Decider;
  kind: "repeat_until";
  max_times: number;
  position: string;
  steps: WorkflowFileStep[];
} | {
  kind: "run_workflow";
  position: string;
  /** The name of a workflow saved in the same workspace. */
  workflow: string;
});

/** The only definition (amended January 2026, decision 80: C-1); the domain part's `WorkflowInput.kind` re-exports it. */
export type WorkflowInputKind = (("document" | "text") | "list");

export type WorkflowOrigin = ({
  crew_run_id: string;
  kind: "saved_from_crew_run";
} | {
  kind: "drafted_by_ordin";
} | {
  from_version: number;
  from_workflow_id: string;
  kind: "duplicated";
} | {
  file_name: string;
  imported_on: Timestamp;
  kind: "imported";
});

export interface WorkflowShare {
  changed_here_not_sent: boolean;
  file_name: string;
  folder: string;
  followed_by: string;
  followed_commit: string;
  followed_date: Timestamp;
  host: ShareHost;
  newer_in_repository: boolean;
  repository: string;
}

export type WorkflowState = "not_saved_yet" | "saved" | "needs_agents";

export interface WorkflowSummary {
  latest_version?: number | null;
  name: string;
  shared?: (WorkflowShare | null);
  state: WorkflowState;
  workflow_id: string;
}

export interface WorkflowView {
  /** Per `agents[].key`. */
  agents: AgentPresence[];
  /** The version's content, format 3. */
  file: WorkflowFile;
  version?: number | null;
  /** Newest first. */
  versions: VersionLine[];
  workflow: Workflow;
}

